u32 kvm_apic_get_current_count(struct kvm_lapic *apic) {
    u64 remaining_time;
    u32 timer_period;
    u32 timer_count = 0;

    if (!apic)
        return 0;

    if (apic->timer.initial_count == 0 || apic->timer.period == 0)
        return 0;

    remaining_time = apic->timer.initial_count - apic->timer.current_count;
    if (remaining_time < 0)
        return 0;

    timer_period = apic->timer.period;
    remaining_time %= timer_period;

    if (timer_period > 0) {
        timer_count = (u32)(remaining_time / (timer_period / apic->divide_count));
    }

    return timer_count;
}
